using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type" in EF Core 9.
            // Existing 500K documents use "Discriminator". Preserve the old property name so EF Core 9
            // can still read/query them, and so direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|KeyValue" (e.g. "Product|123")
            // to just the raw key value in EF Core 9. Existing documents use the old format.
            // Preserve it so EF Core 9 can find existing documents by their id.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

// Generates id values in the legacy "Product|<key>" format that EF Core 8 used,
// so new documents are consistent with the existing 500K.
